  2081,
  'S',
  '3701007',
  'Servicio de educación informal en Derechos Humanos, Derecho Internacional Humanitario y organizaciones étnicas',
  'Son  acciones que se realizan para contribuir al  conocimiento y apropiación por parte de autoridades y comunidades de las obligaciones en prevención, así como de herramientas para la puesta en marcha de forma articulada del modelo de Gestión Preventiva del Riesgo mediante el desarrollo de un sistema eficaz de aprendizaje, capacitación y entrenamiento basado en la construcción de visión compartida. Así mismo, estas acciones buscan al crecimiento de las capacidades intelectuales  y la  apropiación por parte de las comunidades negras  en su mejoramiento y fortalecimiento con el fin de  impulsar su igualdad económica y el reconocimiento de su diversidad cultural. Finalmente, se promueve el conocimiento cultural y ancestral de la  población indígena  como estrategia de pervivencia de su cultura y expresión sociocultural.',
  NULL,
  168,
  NULL,
  NULL,
  NULL,
  'N',
