  'Infraestructura educativa mejorada',
  'Contempla los diferentes tipos de intervención por mejoramiento de la infraestructura escolar existente en las categorías de:1. Mejoramiento: Corresponden a intervenciones de obras menores o de mejoramiento de elementos constructivos, para el mejoramiento de las condiciones de uso y operación de la infraestructura frente a condiciones de riesgo o mantenimiento.2.Reforzamiento: Corresponde a las obras de rehabilitación de sistemas portantes, estructurales y demás elementos constructivos según la NSR 10. 3. Restauración: Hace referencia a la rehabilitación de elementos de carácter patrimonial, cultural o de conservación arquitectónica. 4. Ampliación o nuevas etapas: Corresponde a la ejecución de obras nuevas de ampliación o de nuevas etapas dentro de sedes existentes para complementar y MEJORAR las condiciones de operatividad de la infraestructura existente. Aquí se podrían llegar a generar nuevos cupos.5 Restitución o reubicación parcial en la sede existente: Se refiere a las obras de r',
