  2169,
  'S',
  '3708009',
  'Estaciones de bomberos construidas',
  'Hace referencia a la construcción y dotación de estaciones de bomberos (Clase 1, 2, 3 o 4). Las Estaciones de bomberos son las infraestructuras que protegen los bienes materiales y recursos técnicos para la atención de emergencias; como lo son los vehículos y el equipamiento (Resolución 661 de 2014).',
