  2170,
  'S',
  '3708014',
  'Servicio de asistencia técnica y administrativa de los cuerpos de bomberos del país',
  'Incluye el apoyo a los cuerpos de bomberos en la implementación de políticas y reglamentos de orden técnico, administrativo y operativo, así como la formulación de estrategias, planes y demás herramientas para los cuerpos de bomberos del país en: prevención y atención de incendios, preparativos y atención de rescates en todas sus modalidades, así como atención de incidenes con materiales peligrosos.',
