  2171,
  'S',
  '3708012',
  'Servicio de certificación a Cuerpos de Bomberos de Colombia',
  ' La Dirección Nacional de Bomberos de Colombia ejerce la inspección, vigilancia y control sobre los Cuerpos de Bomberos de Colombia conforme a lo establecido en el art. 24 de la ley 1575 de 2012. De acuerdo a lo anterior, mediante el certificado de cumplimiento expedido por la Dirección Nacional de Bomberos se acredita que un cuerpo de bomberos está capacitado para la prestación del servicio público esencial de bomberos.',
