  'Servicio de apoyo a la estrategia de monitoreo, seguimiento y control a los recursos del Sistema General de Participaciones SGP - Agua Potable y Saneamiento Básico',
  'Acciones encaminadas a analizar el comportamiento del uso de los recursos del SGP-APSB por parte de las Entidades Territoriales para generar alertas tempranas que permitan mejorar la gestión de las mismas. Se desarrolla el Informe de Monitoreo Nacional, mediante el cual se presenta el comportamiento anual del uso de los recursos del SGP-APSB y se socializa a las diferentes entidades del sector.',
