  'Apoyo técnico para identificar y determinar planes de reparación colectiva para grupos, comunidades y organizaciones sociales, sindicales y políticas, que han sufrido eventos definidos en el art. 151 de la Ley 1448. Las medidas que pueden incluir los planes son: restitución, indemnización, rehabilitación, satisfacción y garantías de no repetición, en los componentes político, material y simbólico',
