  'Mediante los cuales se activan mecanismos que permiten neutralizar o superar las causas y circunstancias que generan riesgo en el marco del conflicto armado interno y así evitar la ocurrencia de violaciones de Derechos Humanos e infracciones al Derecho Internacional Humanitario desde la competencia del sector Inclusión Social. ',
