  '4101065',
  'Servicios de apoyo financiero para la restitución de créditos y pasivos',
  'Facilita acceso al crédito de la población víctima, acorde con el   artículo 129 de la Ley 1448 de 2011.  Establece el derecho de las víctimas que desarrollen actividades formales del sector comercial y agropecuario, a acceder a líneas de redescuento de créditos en condiciones preferenciales.  La  Unidad  mediante el apalancamiento de recursos actúa articuladamente  con Bancoldex y Finagro ofreciendo una Línea  especial  de crédito  con una tasa de redescuento compensada.',
